const PR58=[{label:"Ví dụ: Floyd-Warshall",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    const int INF = 1000000000;\n    int n = 4;\n    int d[5][5];\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++) d[i][j] = (i == j) ? 0 : INF;\n    d[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2;\n    d[3][1] = 5; d[3][4] = 1; d[4][1] = 2;\n    for (int k = 1; k <= n; k++)                   // đỉnh trung gian được phép dùng\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= n; j++)\n                if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])\n                    d[i][j] = d[i][k] + d[k][j];\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= n; j++) cout << d[i][j] << \" \";\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"graph",mat:"d",dir:true,inf:1000000000,cur:["i","j"]},{type:"grid",of:"d"},{type:"vars",names:["k","i","j"]}],py:{code:"INF = float(\"inf\")\nn = 4\nd = [[0 if i == j else INF for j in range(n + 1)] for i in range(n + 1)]\nd[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2\nd[3][1] = 5; d[3][4] = 1; d[4][1] = 2\nfor k in range(1, n + 1):              # đỉnh trung gian được phép dùng\n    for i in range(1, n + 1):\n        for j in range(1, n + 1):\n            if d[i][k] + d[k][j] < d[i][j]:\n                d[i][j] = d[i][k] + d[k][j]\nfor i in range(1, n + 1):\n    print(*d[i][1:])",note:"Bảng sau cùng: hàng 1 là 0 3 5 6 (1 → 2 → 3 → 4 dài 3 + 2 + 1 = 6, ngắn hơn cạnh thẳng 7). Trong Python, float(\"inf\") cộng thêm vẫn là inf nên không cần kiểm tra trước khi cộng. Hàng 0, cột 0 không dùng.",viz:[{type:"grid",of:"d"},{type:"vars",names:["k","i","j"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        const int INF = 1000000000;\n        int n = 4;\n        int[][] d = new int[n + 1][];\n        for (int i = 0; i <= n; i++)\n        {\n            d[i] = new int[n + 1];\n            for (int j = 0; j <= n; j++) d[i][j] = i == j ? 0 : INF;\n        }\n        d[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2;\n        d[3][1] = 5; d[3][4] = 1; d[4][1] = 2;\n        for (int k = 1; k <= n; k++)           // đỉnh trung gian được phép dùng\n            for (int i = 1; i <= n; i++)\n                for (int j = 1; j <= n; j++)\n                    if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])\n                        d[i][j] = d[i][k] + d[k][j];\n        for (int i = 1; i <= n; i++)\n        {\n            for (int j = 1; j <= n; j++) Console.Write(d[i][j] + \" \");\n            Console.WriteLine();\n        }\n    }\n}"}},{label:"Ví dụ: Ai đi tới được ai (bao đóng bắc cầu)",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n = 4;\n    bool toi[5][5] = {};\n    toi[1][2] = toi[2][3] = toi[4][1] = true;   // cạnh có hướng\n    for (int i = 1; i <= n; i++) toi[i][i] = true;\n    for (int k = 1; k <= n; k++)\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= n; j++)\n                if (toi[i][k] && toi[k][j]) toi[i][j] = true;   // i tới k, k tới j\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= n; j++) cout << toi[i][j];\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"grid",of:"toi",ptr:["i","j"]},{type:"vars",names:["k"]}],py:{code:"n = 4\ntoi = [[i == j for j in range(n + 1)] for i in range(n + 1)]\nfor u, v in [(1, 2), (2, 3), (4, 1)]:  # cạnh có hướng\n    toi[u][v] = True\nfor k in range(1, n + 1):\n    for i in range(1, n + 1):\n        for j in range(1, n + 1):\n            if toi[i][k] and toi[k][j]:  # i tới k, k tới j\n                toi[i][j] = True\nfor i in range(1, n + 1):\n    print(\"\".join(\"1\" if x else \"0\" for x in toi[i][1:]))"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 4;\n        bool[][] toi = new bool[n + 1][];\n        for (int i = 0; i <= n; i++) { toi[i] = new bool[n + 1]; toi[i][i] = true; }\n        toi[1][2] = toi[2][3] = toi[4][1] = true;   // cạnh có hướng\n        for (int k = 1; k <= n; k++)\n            for (int i = 1; i <= n; i++)\n                for (int j = 1; j <= n; j++)\n                    if (toi[i][k] && toi[k][j]) toi[i][j] = true;   // i tới k, k tới j\n        for (int i = 1; i <= n; i++)\n        {\n            for (int j = 1; j <= n; j++) Console.Write(toi[i][j] ? 1 : 0);\n            Console.WriteLine();\n        }\n    }\n}"}},{label:"Ví dụ: Truy vết đường đi",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    const int INF = 1000000000;\n    int n = 4;\n    int d[5][5];\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++) d[i][j] = (i == j) ? 0 : INF;\n    d[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2;\n    d[3][1] = 5; d[3][4] = 1; d[4][1] = 2;\n    int sau[5][5];                     // sau[i][j]: đỉnh kế tiếp sau i trên đường ngắn nhất tới j\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++) sau[i][j] = (d[i][j] < INF) ? j : 0;\n    for (int k = 1; k <= n; k++)\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= n; j++)\n                if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j]) {\n                    d[i][j] = d[i][k] + d[k][j];\n                    sau[i][j] = sau[i][k];       // đi về phía k trước\n                }\n    int u = 2, v = 4;\n    cout << d[u][v] << \":\";\n    for (int x = u; x != v; x = sau[x][v]) cout << \" \" << x;\n    cout << \" \" << v << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"sau",ptr:["i","j"]}],py:{code:"INF = float(\"inf\")\nn = 4\nd = [[0 if i == j else INF for j in range(n + 1)] for i in range(n + 1)]\nd[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2\nd[3][1] = 5; d[3][4] = 1; d[4][1] = 2\nsau = [[j if d[i][j] < INF else 0 for j in range(n + 1)] for i in range(n + 1)]   # bước kế tiếp\nfor k in range(1, n + 1):\n    for i in range(1, n + 1):\n        for j in range(1, n + 1):\n            if d[i][k] + d[k][j] < d[i][j]:\n                d[i][j] = d[i][k] + d[k][j]\n                sau[i][j] = sau[i][k]  # đi về phía k trước\nu, v = 2, 4\nduong = [u]\nx = u\nwhile x != v:\n    x = sau[x][v]\n    duong.append(x)\nprint(str(d[u][v]) + \":\", *duong)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        const int INF = 1000000000;\n        int n = 4;\n        int[][] d = new int[n + 1][];\n        for (int i = 0; i <= n; i++)\n        {\n            d[i] = new int[n + 1];\n            for (int j = 0; j <= n; j++) d[i][j] = i == j ? 0 : INF;\n        }\n        d[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2;\n        d[3][1] = 5; d[3][4] = 1; d[4][1] = 2;\n        int[][] sau = new int[n + 1][];        // sau[i][j]: đỉnh kế tiếp sau i trên đường ngắn nhất tới j\n        for (int i = 0; i <= n; i++)\n        {\n            sau[i] = new int[n + 1];\n            for (int j = 0; j <= n; j++) sau[i][j] = d[i][j] < INF ? j : 0;\n        }\n        for (int k = 1; k <= n; k++)\n            for (int i = 1; i <= n; i++)\n                for (int j = 1; j <= n; j++)\n                    if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])\n                    {\n                        d[i][j] = d[i][k] + d[k][j];\n                        sau[i][j] = sau[i][k];   // đi về phía k trước\n                    }\n        int u = 2, v = 4;\n        Console.Write(d[u][v] + \":\");\n        for (int x = u; x != v; x = sau[x][v]) Console.Write(\" \" + x);\n        Console.WriteLine(\" \" + v);\n    }\n}"}},{label:"Ví dụ: Phát hiện chu trình âm",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    const int INF = 1000000000;\n    int n = 3;\n    int d[4][4];\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++) d[i][j] = (i == j) ? 0 : INF;\n    d[1][2] = 1; d[2][3] = -3; d[3][1] = 1;      // 1 -> 2 -> 3 -> 1 dài -1\n    for (int k = 1; k <= n; k++)                   // đỉnh trung gian được phép dùng\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= n; j++)\n                if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])\n                    d[i][j] = d[i][k] + d[k][j];\n    bool am = false;\n    for (int i = 1; i <= n; i++)\n        if (d[i][i] < 0) am = true;              // đi vòng về chính mình còn “lời”\n    cout << (am ? \"co chu trinh am\" : \"khong\") << \"\\n\";\n    return 0;\n}",viz:[{type:"grid",of:"d",ptr:["i","j"]}],py:{code:"INF = float(\"inf\")\nn = 3\nd = [[0 if i == j else INF for j in range(n + 1)] for i in range(n + 1)]\nd[1][2] = 1; d[2][3] = -3; d[3][1] = 1  # 1 -> 2 -> 3 -> 1 dài -1\nfor k in range(1, n + 1):              # đỉnh trung gian được phép dùng\n    for i in range(1, n + 1):\n        for j in range(1, n + 1):\n            if d[i][k] + d[k][j] < d[i][j]:\n                d[i][j] = d[i][k] + d[k][j]\nam = any(d[i][i] < 0 for i in range(1, n + 1))   # đi vòng về chính mình còn “lời”\nprint(\"co chu trinh am\" if am else \"khong\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        const int INF = 1000000000;\n        int n = 3;\n        int[][] d = new int[n + 1][];\n        for (int i = 0; i <= n; i++)\n        {\n            d[i] = new int[n + 1];\n            for (int j = 0; j <= n; j++) d[i][j] = i == j ? 0 : INF;\n        }\n        d[1][2] = 1; d[2][3] = -3; d[3][1] = 1;    // 1 -> 2 -> 3 -> 1 dài -1\n        for (int k = 1; k <= n; k++)           // đỉnh trung gian được phép dùng\n            for (int i = 1; i <= n; i++)\n                for (int j = 1; j <= n; j++)\n                    if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])\n                        d[i][j] = d[i][k] + d[k][j];\n        bool am = false;\n        for (int i = 1; i <= n; i++)\n            if (d[i][i] < 0) am = true;          // đi vòng về chính mình còn “lời”\n        Console.WriteLine(am ? \"co chu trinh am\" : \"khong\");\n    }\n}"}},{label:"Lỗi: đặt vòng k ở trong cùng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    const int INF = 1000000000;\n    int n = 4;\n    int d[5][5];\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++) d[i][j] = (i == j) ? 0 : INF;\n    d[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2;\n    d[3][1] = 5; d[3][4] = 1; d[4][1] = 2;\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++)\n            for (int k = 1; k <= n; k++)       // SAI: k phải ở ngoài cùng\n                if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])\n                    d[i][j] = d[i][k] + d[k][j];\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= n; j++) cout << d[i][j] << \" \";\n        cout << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"grid",of:"d",ptr:["i","j"]}],py:{code:"INF = float(\"inf\")\nn = 4\nd = [[0 if i == j else INF for j in range(n + 1)] for i in range(n + 1)]\nd[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2\nd[3][1] = 5; d[3][4] = 1; d[4][1] = 2\nfor i in range(1, n + 1):\n    for j in range(1, n + 1):\n        for k in range(1, n + 1):      # SAI: k phải ở ngoài cùng\n            if d[i][k] + d[k][j] < d[i][j]:\n                d[i][j] = d[i][k] + d[k][j]\nfor i in range(1, n + 1):\n    print(*d[i][1:])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        const int INF = 1000000000;\n        int n = 4;\n        int[][] d = new int[n + 1][];\n        for (int i = 0; i <= n; i++)\n        {\n            d[i] = new int[n + 1];\n            for (int j = 0; j <= n; j++) d[i][j] = i == j ? 0 : INF;\n        }\n        d[1][2] = 3; d[2][1] = 8; d[1][4] = 7; d[2][3] = 2;\n        d[3][1] = 5; d[3][4] = 1; d[4][1] = 2;\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= n; j++)\n                for (int k = 1; k <= n; k++)   // SAI: k phải ở ngoài cùng\n                    if (d[i][k] < INF && d[k][j] < INF && d[i][k] + d[k][j] < d[i][j])\n                        d[i][j] = d[i][k] + d[k][j];\n        for (int i = 1; i <= n; i++)\n        {\n            for (int j = 1; j <= n; j++) Console.Write(d[i][j] + \" \");\n            Console.WriteLine();\n        }\n    }\n}"}}];
