makeEx2(document.getElementById("ex-l58"),sim58,[{t:"Bảng khoảng cách giữa các tỉnh",d:"n tỉnh, m con đường hai chiều có độ dài; q câu hỏi “u v”. Đầu vào: n m (1 ≤ n ≤ 100, 0 ≤ m ≤ n²) rồi m dòng u v w (1 ≤ w ≤ 10^6); dòng q (1 ≤ q ≤ 10^4) rồi q dòng u v. Đầu ra: mỗi câu hỏi in độ dài đường ngắn nhất, hoặc -1 nếu không đi được.",tests:[{in:"4 4\n1 2 3\n2 3 2\n3 4 1\n1 4 7\n4\n1 4\n4 2\n3 3\n2 1",out:"6\n3\n0\n3"},{in:"3 1\n1 2 5\n2\n1 3\n2 1",out:"-1\n5"},{in:"3 2\n1 2 5\n1 2 2\n1\n2 1",out:"2"},{in:"20 40\n19 7 14\n7 2 13\n15 13 23\n10 9 29\n20 14 19\n19 4 1\n16 7 31\n3 15 36\n13 12 4\n4 5 20\n2 6 19\n10 6 40\n20 8 49\n3 6 13\n15 5 9\n5 8 2\n9 20 44\n4 16 33\n19 9 38\n11 19 26\n5 10 17\n7 15 13\n20 8 30\n20 3 12\n3 16 47\n10 11 45\n15 16 17\n16 5 50\n3 5 3\n17 8 3\n10 2 3\n7 19 5\n4 2 32\n2 18 46\n9 16 46\n20 11 21\n17 2 23\n3 5 10\n7 20 43\n12 14 7\n30\n16 5\n7 19\n7 1\n2 5\n19 2\n12 14\n12 16\n3 12\n2 17\n13 20\n15 14\n3 11\n4 19\n7 13\n5 19\n4 6\n13 4\n2 7\n4 17\n13 8\n10 18\n15 2\n13 18\n2 6\n10 4\n18 10\n4 14\n1 15\n20 2\n19 7",out:"26\n5\n-1\n20\n18\n7\n44\n38\n23\n30\n34\n33\n1\n36\n21\n36\n42\n13\n25\n34\n49\n26\n95\n19\n22\n49\n53\n-1\n35\n5"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    const long long INF = 1e18;\n    vector<vector<long long>> d(n + 1, vector<long long>(n + 1, INF));\n    for (int i = 1; i <= n; i++) d[i][i] = 0;\n    for (int e = 0; e < m; e++) {\n        int u, v;\n        long long w;\n        cin >> u >> v >> w;\n        // có thể có nhiều đường giữa cùng một cặp: giữ đường ngắn nhất\n    }\n    // Floyd-Warshall\n    int q;\n    cin >> q;\n    for (int t = 0; t < q; t++) {\n        int u, v;\n        cin >> u >> v;\n        cout << (d[u][v] == INF ? -1 : d[u][v]) << \"\\n\";\n    }\n    return 0;\n}",py:{start:"n, m = map(int, input().split())\nINF = float(\"inf\")\nd = [[0 if i == j else INF for j in range(n + 1)] for i in range(n + 1)]\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    d[u][v] = min(d[u][v], w)\n    d[v][u] = min(d[v][u], w)\n# Floyd-Warshall\nq = int(input())\nout = []\nfor _ in range(q):\n    u, v = map(int, input().split())\n    out.append(-1 if d[u][v] == INF else d[u][v])\nprint(\"\\n\".join(map(str, out)))",hints:["Khởi tạo d[i][i] = 0, d[u][v] = min(d[u][v], w) cho mỗi đường (cả hai chiều), còn lại INF.","Floyd-Warshall với k ở vòng ngoài cùng; sau đó trả lời mỗi câu hỏi trong O(1).","Mẹo cho Python: lấy sẵn di = d[i], dk = d[k] ra biến và bỏ qua i khi d[i][k] = INF để đỡ chậm."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        const long INF = (long)1e18;\n        long[][] d = new long[n + 1][];\n        for (int i = 0; i <= n; i++)\n        {\n            d[i] = new long[n + 1];\n            for (int j = 0; j <= n; j++) d[i][j] = i == j ? 0 : INF;\n        }\n        for (int e = 0; e < m; e++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            int u = (int)t[0], v = (int)t[1];\n            d[u][v] = Math.Min(d[u][v], t[2]);\n            d[v][u] = Math.Min(d[v][u], t[2]);\n        }\n        // Floyd-Warshall\n        int q = int.Parse(Console.ReadLine());\n        var sb = new StringBuilder();\n        for (int t = 0; t < q; t++)\n        {\n            int[] uv = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            long r = d[uv[0]][uv[1]];\n            sb.Append(r == INF ? -1 : r).Append('\\n');\n        }\n        Console.Write(sb.ToString());\n    }\n}",hints:["Khởi tạo d[i][i] = 0, d[u][v] = min(d[u][v], w) cho mỗi đường (cả hai chiều), còn lại INF.","Floyd-Warshall với k ở vòng ngoài cùng; sau đó trả lời mỗi câu hỏi trong O(1).","INF = 10^18 thì INF + INF vẫn vừa long, không cần kiểm tra trước khi cộng."]}},{t:"Đặt trạm cứu hỏa",d:"n khu dân cư nối với nhau bởi m con đường hai chiều (đồ thị liên thông). Đặt trạm cứu hỏa ở một khu sao cho quãng đường tới khu xa trạm nhất là nhỏ nhất. Đầu vào: n m (1 ≤ n ≤ 100) rồi m dòng u v w (1 ≤ w ≤ 10^6). Đầu ra: số hiệu khu đặt trạm và quãng đường xa nhất đó; nếu nhiều khu như nhau, chọn khu có số hiệu nhỏ nhất.",tests:[{in:"4 4\n1 2 3\n2 3 2\n3 4 1\n1 4 7",out:"2 3"},{in:"1 0\n",out:"1 0"},{in:"3 2\n1 2 5\n2 3 5",out:"2 5"},{in:"5 4\n1 2 1\n1 3 1\n1 4 1\n1 5 1",out:"1 1"},{in:"20 35\n1 2 9\n1 3 12\n2 4 5\n2 5 4\n1 6 5\n3 7 14\n4 8 11\n3 9 30\n4 10 15\n5 11 18\n5 12 12\n2 13 28\n7 14 22\n10 15 23\n6 16 1\n5 17 12\n6 18 3\n11 19 17\n6 20 29\n17 7 16\n8 20 12\n8 5 1\n15 17 17\n16 18 5\n15 6 28\n1 6 28\n20 5 20\n11 3 27\n5 7 15\n20 11 14\n17 15 13\n14 4 29\n9 1 17\n4 11 4\n3 16 28",out:"2 34"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    const long long INF = 1e18;\n    vector<vector<long long>> d(n + 1, vector<long long>(n + 1, INF));\n    for (int i = 1; i <= n; i++) d[i][i] = 0;\n    for (int e = 0; e < m; e++) {\n        int u, v;\n        long long w;\n        cin >> u >> v >> w;\n        d[u][v] = min(d[u][v], w);\n        d[v][u] = min(d[v][u], w);\n    }\n    // Floyd-Warshall; với mỗi khu i, xa nhất = max d[i][j]; chọn i có giá trị nhỏ nhất\n    cout << 1 << \" \" << 0 << \"\\n\";\n    return 0;\n}",py:{start:"n, m = map(int, input().split())\nINF = float(\"inf\")\nd = [[0 if i == j else INF for j in range(n + 1)] for i in range(n + 1)]\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    d[u][v] = min(d[u][v], w)\n    d[v][u] = min(d[v][u], w)\n# Floyd-Warshall; với mỗi khu i, xa nhất = max d[i][j]; chọn i có giá trị nhỏ nhất\nprint(1, 0)",hints:["Cần khoảng cách giữa mọi cặp khu: Floyd-Warshall.","Với mỗi khu i, quãng đường tới khu xa nhất là max(d[i][1:]). Chọn i làm giá trị đó nhỏ nhất.","Duyệt i tăng dần và chỉ cập nhật khi nhỏ hơn hẳn để giữ số hiệu nhỏ nhất."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        const long INF = (long)1e18;\n        long[][] d = new long[n + 1][];\n        for (int i = 0; i <= n; i++)\n        {\n            d[i] = new long[n + 1];\n            for (int j = 0; j <= n; j++) d[i][j] = i == j ? 0 : INF;\n        }\n        for (int e = 0; e < m; e++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            int u = (int)t[0], v = (int)t[1];\n            d[u][v] = Math.Min(d[u][v], t[2]);\n            d[v][u] = Math.Min(d[v][u], t[2]);\n        }\n        // Floyd-Warshall; với mỗi khu i, xa nhất = max d[i][j]; chọn i có giá trị nhỏ nhất\n        Console.WriteLine(1 + \" \" + 0);\n    }\n}",hints:["Cần khoảng cách giữa mọi cặp khu: Floyd-Warshall.","Với mỗi khu i, quãng đường tới khu xa nhất là max d[i][j] theo j. Chọn i làm giá trị đó nhỏ nhất.","Duyệt i tăng dần và chỉ cập nhật khi nhỏ hơn hẳn để giữ số hiệu nhỏ nhất."]}},{t:"Biết chắc ai mạnh hơn",d:"Giải cờ có n kỳ thủ; m kết quả “u v” nghĩa là u thắng v. Nếu u thắng v và v thắng x thì ta coi như biết chắc u mạnh hơn x (và cứ thế nối tiếp). Đầu vào: n m (1 ≤ n ≤ 100, 0 ≤ m ≤ 4950) rồi m dòng u v. Đầu ra: số cặp có thứ tự (u, v), u ≠ v, mà biết chắc u mạnh hơn v.",tests:[{in:"4 3\n1 2\n2 3\n4 1",out:"6"},{in:"3 0\n",out:"0"},{in:"3 3\n1 2\n2 3\n3 1",out:"6"},{in:"5 2\n1 2\n3 4",out:"2"},{in:"20 30\n9 12\n8 13\n6 10\n6 17\n12 15\n8 15\n5 20\n7 20\n15 17\n3 16\n8 9\n1 15\n17 18\n3 6\n5 16\n14 17\n10 13\n11 12\n1 18\n1 6\n13 15\n2 10\n1 12\n6 18\n5 17\n9 10\n6 16\n6 12\n8 15\n7 9",out:"72"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<bool>> toi(n + 1, vector<bool>(n + 1, false));\n    for (int e = 0; e < m; e++) {\n        int u, v;\n        cin >> u >> v;\n        toi[u][v] = true;\n    }\n    // bao đóng bắc cầu bằng Floyd-Warshall (và/hoặc), rồi đếm các cặp u != v\n    cout << 0 << \"\\n\";\n    return 0;\n}",py:{start:"n, m = map(int, input().split())\ntoi = [[False] * (n + 1) for _ in range(n + 1)]\nfor _ in range(m):\n    u, v = map(int, input().split())\n    toi[u][v] = True\n# bao đóng bắc cầu bằng Floyd-Warshall (and/or), rồi đếm các cặp u != v\nprint(0)",hints:["“Biết chắc u mạnh hơn v” nghĩa là có đường đi u → v: bao đóng bắc cầu.","Floyd-Warshall phiên bản đúng/sai: toi[i][j] = toi[i][j] or (toi[i][k] and toi[k][j]), k ở vòng ngoài.","Đếm các cặp i ≠ j có toi[i][j]."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        bool[][] toi = new bool[n + 1][];\n        for (int i = 0; i <= n; i++) toi[i] = new bool[n + 1];\n        for (int e = 0; e < m; e++)\n        {\n            int[] t = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            toi[t[0]][t[1]] = true;\n        }\n        // bao đóng bắc cầu bằng Floyd-Warshall (&&, ||), rồi đếm các cặp u != v\n        Console.WriteLine(0);\n    }\n}",hints:["“Biết chắc u mạnh hơn v” nghĩa là có đường đi u → v: bao đóng bắc cầu.","Floyd-Warshall phiên bản đúng/sai: toi[i][j] = toi[i][j] || (toi[i][k] && toi[k][j]), k ở vòng ngoài.","Đếm các cặp i ≠ j có toi[i][j]."]}}]);

